<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use App\Models\{User,Attendance,Assessment,Module,Lesson,SessionPlan,Observation,CpdSession,Followup,Audit,StaffAttendance,Portfolio,Student};
class SupervisionController extends Controller{
private function ok($r){abort_unless(in_array($r->user()->role,['dosb','dost']),403);}
public function index(Request $r){$u=$r->user();abort_unless(in_array($u->role,['dosb','dost','head']),403);$head=$u->role==='head';$classes=$u->classes()->orderBy('id')->get();$ids=$classes->pluck('id');
$rows=$classes->map(fn($c)=>['c'=>$c,'t'=>$c->trainer?->name,'n'=>$c->students()->count(),'last'=>Attendance::where('school_class_id',$c->id)->max('date'),'pend'=>Assessment::where('school_class_id',$c->id)->whereNull('locked_at')->count(),'done'=>Assessment::where('school_class_id',$c->id)->whereNotNull('locked_at')->count(),'nop'=>Student::where('school_class_id',$c->id)->whereNotIn('id',Portfolio::where('kind','student')->where('created_at','>=',now()->subDays(30))->pluck('student_id'))->count()]);
$trainers=User::where('role','trainer')->whereIn('id',$classes->pluck('trainer_id')->filter())->get()->map(function($t)use($classes){$mine=$classes->where('trainer_id',$t->id);$cid=$mine->pluck('id');$p=SessionPlan::where('user_id',$t->id);
return['t'=>$t,'classes'=>$mine->pluck('name')->implode(', '),'modules'=>Module::whereIn('school_class_id',$cid)->count(),'lessons'=>(Lesson::where('trainer_id',$t->id)->count()?:Lesson::whereIn('school_class_id',$cid)->count()),'plans'=>(clone $p)->count(),'done'=>(clone $p)->where('delivered',1)->count(),'over'=>(clone $p)->where('delivered',0)->whereDate('date','<',today())->count(),'port'=>Portfolio::where('kind','trainer')->where('user_id',$t->id)->max('created_at')];});
$dos=collect();$staff=collect();
if($head){$dos=User::whereIn('role',['dosb','dost'])->get()->map(fn($d)=>['d'=>$d,'fu'=>Followup::where('user_id',$d->id)->count(),'obs'=>Observation::where('observer_id',$d->id)->count(),'tt'=>\App\Models\Audit::where('user_id',$d->id)->where('action','Timetable updated')->count()]);
$staff=User::whereIn('role',['dosb','dost','trainer','accountant','storekeeper'])->orderBy('role')->orderBy('name')->get()->map(function($s){$g=StaffAttendance::where('user_id',$s->id)->where('date','>=',today()->subDays(29))->get();$n=$g->count();$p=$g->whereIn('status',['P','L'])->count();return['s'=>$s,'n'=>$n,'a'=>$g->where('status','A')->count(),'pct'=>$n?round($p/$n*100):null];});}
return view('supervision',['head'=>$head,'cn'=>$classes->pluck('name','id'),'pending'=>Assessment::with('module')->whereIn('school_class_id',$ids)->whereNull('locked_at')->orderBy('deadline')->get(),'dos'=>$dos,'staff'=>$staff,'rows'=>$rows,'trainers'=>$trainers,
'plans'=>SessionPlan::with('schoolClass','user')->whereIn('school_class_id',$ids)->orderByDesc('date')->take(25)->get(),'obs'=>Observation::with('trainer','observer')->latest()->take(15)->get(),'cpd'=>CpdSession::latest()->take(10)->get(),'tlist'=>User::where('role','trainer')->orderBy('name')->get()]);}
public function deadline(Request $r,Assessment $assessment){$this->ok($r);abort_unless($r->user()->classes()->where('id',$assessment->school_class_id)->exists(),403);$v=$r->validate(['deadline'=>'nullable|date']);$assessment->update(['deadline'=>$v['deadline']??null]);Audit::log('Mark-entry deadline set',$assessment->title);return back()->with('ok','Deadline saved.');}
public function observe(Request $r){$this->ok($r);$v=$r->validate(['trainer_id'=>'required|exists:users,id','date'=>'required|date','rating'=>'required|in:Excellent,Very good,Good,Needs improvement','comments'=>'required|max:1000']);Observation::create($v+['observer_id'=>$r->user()->id]);Audit::log('Classroom observation recorded',User::find($v['trainer_id'])->name);return back()->with('ok','Observation saved.');}
public function cpd(Request $r){$this->ok($r);$v=$r->validate(['title'=>'required|max:150','date'=>'required|date','attendees'=>'nullable|max:500']);CpdSession::create($v+['created_by'=>$r->user()->id]);return back()->with('ok','CPD session recorded.');}}
